#include "pixel_editor.h"
#include "importer.h"
#include <QtWidgets>
namespace cf{
PixelCanvas::PixelCanvas(QWidget *p):QWidget(p){setMouseTracking(true);setFocusPolicy(Qt::StrongFocus);setAccessibleName("Pixel canvas: arrows move the cursor; Space paints; Delete erases");}
void PixelCanvas::reload(){setFixedSize(qMax(80,asset.width*zoom+16),qMax(80,asset.height*zoom+16));update();}
void PixelCanvas::paintEvent(QPaintEvent *){QPainter p(this);p.fillRect(rect(),QColor("#14202c"));if(asset.pixels.isEmpty())return;for(int y=0;y<asset.height;++y)for(int x=0;x<asset.width;++x){int index=quint8(asset.pixels[y*asset.width+x]);QColor color=index==0&&asset.kind=="sprite"?QColor((x+y)%2?"#71808c":"#9ca9b2"):rgb555(asset.palette.value(index));p.fillRect(8+x*zoom,8+y*zoom,zoom,zoom,color);}if(grid&&zoom>=5){p.setPen(QColor(0,0,0,80));for(int x=0;x<=asset.width;++x)p.drawLine(8+x*zoom,8,8+x*zoom,8+asset.height*zoom);for(int y=0;y<=asset.height;++y)p.drawLine(8,8+y*zoom,8+asset.width*zoom,8+y*zoom);}p.setPen(QPen(QColor("#ff6888"),2));p.drawRect(8+cursor.x()*zoom,8+cursor.y()*zoom,zoom,zoom);}
void PixelCanvas::paint(QPoint at,bool erase){int x=(at.x()-8)/zoom,y=(at.y()-8)/zoom;if(at.x()<8||at.y()<8||x>=asset.width||y>=asset.height||asset.pixels.size()!=asset.width*asset.height)return;cursor={x,y};int cell=y*asset.width+x;char color=erase?0:brush;if(asset.pixels[cell]!=color){asset.pixels[cell]=color;changed=true;update();}}
void PixelCanvas::mousePressEvent(QMouseEvent *e){if(e->button()!=Qt::LeftButton&&e->button()!=Qt::RightButton)return;setFocus();drawing=true;changed=false;paint(e->pos(),e->button()==Qt::RightButton);}
void PixelCanvas::mouseMoveEvent(QMouseEvent *e){if(drawing)paint(e->pos(),e->buttons()&Qt::RightButton);}
void PixelCanvas::mouseReleaseEvent(QMouseEvent *){if(drawing&&changed&&onPaint)onPaint(asset.pixels);drawing=false;changed=false;}
void PixelCanvas::paintCursor(){paint(QPoint(8+cursor.x()*zoom+zoom/2,8+cursor.y()*zoom+zoom/2),false);if(changed&&onPaint)onPaint(asset.pixels);changed=false;update();}
void PixelCanvas::keyPressEvent(QKeyEvent *e){if(e->key()==Qt::Key_Left)cursor.rx()=qMax(0,cursor.x()-1);else if(e->key()==Qt::Key_Right)cursor.rx()=qMin(asset.width-1,cursor.x()+1);else if(e->key()==Qt::Key_Up)cursor.ry()=qMax(0,cursor.y()-1);else if(e->key()==Qt::Key_Down)cursor.ry()=qMin(asset.height-1,cursor.y()+1);else if(e->key()==Qt::Key_Space)paintCursor();else if(e->key()==Qt::Key_Delete||e->key()==Qt::Key_Backspace){int old=brush;brush=0;paintCursor();brush=old;}else if(e->key()>=Qt::Key_0&&e->key()<=Qt::Key_3)brush=e->key()-Qt::Key_0;update();e->accept();}
PixelEditor::PixelEditor(QWidget *p):QWidget(p){auto *root=new QHBoxLayout(this);auto *side=new QVBoxLayout;list=new QListWidget;side->addWidget(list,1);auto *sprite=new QPushButton("+ Blank sprite"),*tiles=new QPushButton("+ Blank tileset"),*exportPng=new QPushButton("Export PNG…");side->addWidget(sprite);side->addWidget(tiles);
for(auto kind:{QString("sprite"),QString("tileset")}){auto *import=new QPushButton(kind=="sprite"?"Import sprite / sheet…":"Import tileset…");side->addWidget(import);connect(import,&QPushButton::clicked,this,[this,kind]{if(project.assets.size()>=32){QMessageBox::information(this,"Asset limit","Use up to 32 embedded assets.");return;}RasterAsset asset;if(!importAsset(this,kind,asset))return;auto p=project;p.assets<<asset;selected=asset.id;if(onEdit)onEdit(p);else setProject(p);zoom->setValue(qBound(1,qMin(640/asset.width,512/asset.height),16));});}
side->addWidget(exportPng);auto *left=new QWidget;left->setLayout(side);left->setMaximumWidth(250);root->addWidget(left);auto *center=new QVBoxLayout;auto *bar=new QHBoxLayout;name=new QLineEdit;name->setPlaceholderText("Asset name");bar->addWidget(name,1);zoom=new QSpinBox;zoom->setRange(1,32);zoom->setValue(16);zoom->setPrefix("Zoom ");zoom->setSuffix("×");bar->addWidget(zoom);auto *grid=new QCheckBox("Grid");grid->setChecked(true);bar->addWidget(grid);center->addLayout(bar);auto *palette=new QHBoxLayout;auto *group=new QButtonGroup(this);for(int i=0;i<4;++i){colors[i]=new QPushButton(QString("%1").arg(i));colors[i]->setCheckable(true);group->addButton(colors[i],i);palette->addWidget(colors[i]);connect(colors[i],&QPushButton::clicked,this,[this,i]{canvas->brush=i;});auto *change=new QPushButton("Edit colour…");palette->addWidget(change);connect(change,&QPushButton::clicked,this,[this,i]{auto color=QColorDialog::getColor(rgb555(canvas->asset.palette.value(i)),this,"Palette colour");if(color.isValid())edit([&](RasterAsset &a){a.palette[i]=toRgb555(color);});});}colors[1]->setChecked(true);center->addLayout(palette);canvas=new PixelCanvas;auto *pixelControls=new QHBoxLayout;auto *pixelX=new QSpinBox,*pixelY=new QSpinBox;pixelX->setRange(0,127);pixelY->setRange(0,127);pixelX->setPrefix("Pixel X ");pixelY->setPrefix("Y ");auto *paintPixel=new QPushButton("Paint selected pixel");pixelControls->addWidget(pixelX);pixelControls->addWidget(pixelY);pixelControls->addWidget(paintPixel);pixelControls->addStretch();center->addLayout(pixelControls);connect(paintPixel,&QPushButton::clicked,this,[this,pixelX,pixelY]{canvas->cursor=QPoint(qMin(pixelX->value(),canvas->asset.width-1),qMin(pixelY->value(),canvas->asset.height-1));canvas->paintCursor();});auto *scroll=new QScrollArea;scroll->setWidget(canvas);center->addWidget(scroll,1);center->addWidget(new QLabel("Left drag paints · Right drag erases to colour 0 · Sprite colour 0 is transparent. Arrows + Space also paint. Each stroke is one Undo step."));root->addLayout(center,1);connect(list,&QListWidget::currentRowChanged,this,[this](int i){if(!filling&&i>=0&&i<project.assets.size()){selected=project.assets[i].id;fill();}});connect(name,&QLineEdit::textEdited,this,[this](QString s){edit([&](RasterAsset &a){a.name=s;});});connect(zoom,&QSpinBox::valueChanged,this,[this](int z){canvas->zoom=z;canvas->reload();});connect(grid,&QCheckBox::toggled,this,[this](bool v){canvas->grid=v;canvas->update();});canvas->onPaint=[this](const QByteArray &pixels){edit([&](RasterAsset &a){a.pixels=pixels;});};connect(sprite,&QPushButton::clicked,this,[this]{create("sprite");});connect(tiles,&QPushButton::clicked,this,[this]{create("tileset");});connect(exportPng,&QPushButton::clicked,this,[this]{auto a=project.asset(selected);if(!a)return;QString file=QFileDialog::getSaveFileName(this,"Export artwork",a->name+".png","PNG (*.png)");if(!file.isEmpty()&&!a->image().save(file))QMessageBox::warning(this,"Export failed","Could not write PNG.");});}
void PixelEditor::setProject(const Project &p){filling=true;project=p;if(!p.asset(selected))selected=p.assets.isEmpty()?QString():p.assets[0].id;list->clear();for(auto &a:p.assets)list->addItem(a.name+" · "+a.kind);for(int i=0;i<p.assets.size();++i)if(p.assets[i].id==selected)list->setCurrentRow(i);fill();filling=false;}
void PixelEditor::fill(){auto a=project.asset(selected);name->setEnabled(a);if(!a){canvas->asset={};canvas->reload();return;}if(name->text()!=a->name)name->setText(a->name);canvas->asset=*a;canvas->cursor.setX(qBound(0,canvas->cursor.x(),a->width-1));canvas->cursor.setY(qBound(0,canvas->cursor.y(),a->height-1));for(int i=0;i<4;++i)colors[i]->setStyleSheet("background:"+rgb555(a->palette.value(i)).name()+";color:"+(rgb555(a->palette.value(i)).lightness()<128?"white":"black"));canvas->reload();}
void PixelEditor::edit(const std::function<void(RasterAsset &)> &fn){if(filling)return;auto p=project;for(auto &a:p.assets)if(a.id==selected){fn(a);if(onEdit)onEdit(p);else setProject(p);break;}}
void PixelEditor::create(QString kind){if(project.assets.size()>=32)return;QDialog dialog(this);dialog.setWindowTitle("Blank "+kind);auto *form=new QFormLayout(&dialog);auto *label=new QLineEdit(kind=="sprite"?"New sprite":"New tileset");auto *width=new QSpinBox,*height=new QSpinBox;for(auto *s:{width,height}){s->setRange(8,kind=="sprite"?32:128);s->setSingleStep(8);s->setValue(kind=="sprite"?16:32);}form->addRow("Name",label);form->addRow("Width (pixels, multiple of 8)",width);form->addRow("Height (pixels, multiple of 8)",height);auto *buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);form->addRow(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);if(dialog.exec()!=QDialog::Accepted)return;if(width->value()%8||height->value()%8){QMessageBox::warning(this,"Invalid dimensions","Use dimensions that are multiples of 8.");return;}RasterAsset a;a.id="art_"+QUuid::createUuid().toString(QUuid::Id128).left(8);a.name=label->text();a.kind=kind;a.width=width->value();a.height=height->value();a.pixels=QByteArray(a.width*a.height,0);a.palette={toRgb555(QColor("#e8f0d0")),toRgb555(QColor("#a0c070")),toRgb555(QColor("#508050")),toRgb555(QColor("#183830"))};auto p=project;p.assets<<a;selected=a.id;if(onEdit)onEdit(p);else setProject(p);}
}
